package com.andye.warmod.radar.station.network;import com.andye.warmod.block.RadarStationStructure;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.station.*;import java.util.*;import net.fabricmc.fabric.api.networking.v1.*;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.phys.Vec3;public final class RadarStationNetworking{private static final Map<UUID,Viewer> VIEWERS=new HashMap<>();private static boolean registered;private RadarStationNetworking(){}public static void register(){if(registered)return;PayloadTypeRegistry.clientboundPlay().register(ClientboundOpenRadarStationPayload.TYPE,ClientboundOpenRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundRadarStationObservationPayload.TYPE,ClientboundRadarStationObservationPayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundRadarStationStatePayload.TYPE,ClientboundRadarStationStatePayload.STREAM_CODEC);PayloadTypeRegistry.clientboundPlay().register(ClientboundCloseRadarStationPayload.TYPE,ClientboundCloseRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundCloseRadarStationPayload.TYPE,ServerboundCloseRadarStationPayload.STREAM_CODEC);PayloadTypeRegistry.serverboundPlay().register(ServerboundConfigureRadarStationPayload.TYPE,ServerboundConfigureRadarStationPayload.STREAM_CODEC);ServerPlayNetworking.registerGlobalReceiver(ServerboundCloseRadarStationPayload.TYPE,(p,c)->VIEWERS.remove(c.player().getUUID()));ServerPlayNetworking.registerGlobalReceiver(ServerboundConfigureRadarStationPayload.TYPE,(p,c)->configure(c.player(),p));ServerPlayConnectionEvents.DISCONNECT.register((h,s)->VIEWERS.remove(h.getPlayer().getUUID()));registered=true;}public static void open(ServerPlayer p,RadarStationBlockEntity s){if(p.level()!=s.getLevel()||p.distanceToSqr(Vec3.atCenterOf(s.getBlockPos()))>64)return;VIEWERS.put(p.getUUID(),new Viewer(p,s.radarId(),s.getBlockPos()));ServerPlayNetworking.send(p,new ClientboundOpenRadarStationPayload(s.radarId(),s.getBlockPos(),p.level().dimension().identifier(),p.level().getGameTime(),RadarStationConstants.SWEEP_PERIOD_TICKS,RadarStationConstants.DETECTION_RANGE_BLOCKS,s.warningRadius(),s.fireRadius(),s.redstoneSignal(),s.primaryThreatId(),s.primaryThreatDistance(),s.phaseOffset()));sendState(s);if(!s.observations().isEmpty())sendObservations(s,List.copyOf(s.observations()));}public static void sendObservations(RadarStationBlockEntity s,List<RadarStationObservation> f){send(s,new ClientboundRadarStationObservationPayload(s.radarId(),f));}public static void sendState(RadarStationBlockEntity s){if(s.getLevel()instanceof net.minecraft.server.level.ServerLevel l)send(s,new ClientboundRadarStationStatePayload(s.radarId(),s.warningRadius(),s.fireRadius(),s.redstoneSignal(),s.primaryThreatId(),s.primaryThreatDistance(),s.warningActive(),s.observations().size(),s.threatCount(),l.getGameTime()));}private static void send(RadarStationBlockEntity s,net.minecraft.network.protocol.common.custom.CustomPacketPayload p){VIEWERS.values().removeIf(v->{if(v.radarId.equals(s.radarId())){if(v.player.level()!=s.getLevel()||!s.getBlockPos().equals(v.centre)){ServerPlayNetworking.send(v.player,new ClientboundCloseRadarStationPayload(s.radarId()));return true;}ServerPlayNetworking.send(v.player,p);}return false;});}public static void closeStation(UUID id){VIEWERS.values().removeIf(v->{if(v.radarId.equals(id)){ServerPlayNetworking.send(v.player,new ClientboundCloseRadarStationPayload(id));return true;}return false;});}private static void configure(ServerPlayer player,ServerboundConfigureRadarStationPayload p){Viewer v=VIEWERS.get(player.getUUID());if(v==null||!v.radarId.equals(p.radarId())||!v.centre.equals(p.centre())||!Double.isFinite(p.warningRadius())||!Double.isFinite(p.fireRadius())||player.distanceToSqr(Vec3.atCenterOf(p.centre()))>64)return;if(!(player.level().getBlockEntity(p.centre())instanceof RadarStationBlockEntity s)||!s.radarId().equals(p.radarId())||!RadarStationStructure.complete(player.level(),p.centre(),s.facing()))return;s.configure(p.warningRadius(),p.fireRadius());sendState(s);}private record Viewer(ServerPlayer player,UUID radarId,net.minecraft.core.BlockPos centre){}}